<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$expenseId=(int)($input['expense_id']??0);$rowId=(int)($input['statement_row_id']??0);if($expenseId<=0||$rowId<=0)accounts_fail('REFUND_LINK_REQUIRED');$db=production_db();return accounts_transaction($db,function() use($db,$user,$expenseId,$rowId): array {$e=$db->prepare("SELECT * FROM qbook_general_expenses WHERE id=? AND status='APPROVED' AND journal_id IS NOT NULL FOR UPDATE");$e->execute([$expenseId]);$expense=$e->fetch();if(!$expense)accounts_fail('EXPENSE_NOT_REFUNDABLE',409);$s=$db->prepare("SELECT * FROM qbook_bank_statement_rows WHERE id=? FOR UPDATE");$s->execute([$rowId]);$row=$s->fetch();if(!$row)accounts_fail('BANK_ROW_NOT_FOUND',404);$minor=accounts_money_minor($row['amount'],false);if($minor<=0||(int)$row['bank_account_id']!==(int)$expense['bank_account_id'])accounts_fail('ACTUAL_BANK_CREDIT_REQUIRED',409);$already=$db->prepare("SELECT COALESCE(SUM(amount),0) FROM qbook_general_expense_refunds WHERE expense_id=?");$already->execute([$expenseId]);$existing=accounts_money_minor((string)$already->fetchColumn(),false);$expenseMinor=accounts_money_minor($expense['amount'],false);if($existing+$minor>$expenseMinor)accounts_fail('REFUND_EXCEEDS_EXPENSE',409);$db->prepare("INSERT INTO qbook_general_expense_refunds(expense_id,statement_row_id,amount,linked_by) VALUES(?,?,?,?)")->execute([$expenseId,$rowId,accounts_minor_decimal($minor),(int)$user['id']]);$id=(int)$db->lastInsertId();accounts_audit($db,$user,'GENERAL_EXPENSE_REFUND_LINKED','GENERAL_EXPENSE',$expenseId,['refund_link_id'=>$id,'statement_row_id'=>$rowId,'amount'=>accounts_minor_decimal($minor),'statement_preserved'=>true,'journal_posted'=>false]);return ['refund_link'=>['id'=>$id,'expense_id'=>$expenseId,'statement_row_id'=>$rowId,'amount'=>accounts_minor_decimal($minor)],'journal_posted'=>false];});});
